function result=runV4BEnhancedMechanismPass()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();p=v4DefaultBParameters();schedule=v4ContinuousPassSchedule(c);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());errors=zeros(3,4);eligible=0;
for frameIndex=1:schedule.frameCount,ledger=v4RandomLedger(c,'validation',3,1,frameIndex);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;if ~schedule.metricEligible(frameIndex),state.cross=struct();continue,end;eligible=eligible+1;bootstrap=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);measurement=schedule.frameStartTimeSec(frameIndex)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(bootstrap.cfoBins),bootstrap.rateBinsPerSec,c,p);rx=cell(3,1);rx{1}=v4HuangStaticDecode(frame.observation,bootstrap,c);rx{2}=v4Stage55DualBranchDecode(frame.observation,bootstrap,c,p,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount);rx{3}=v4PaperMidambleDecode(frame.observation,bootstrap,c,p);for method=1:3,m=v4EvaluateFrame(rx{method},frame.truth,c);errors(method,:)=errors(method,:)+[m.symbolErrors m.hardBitErrors m.softBitErrors m.packetError];end;end
den=[eligible*112 eligible*768 eligible*768 eligible];metrics=errors./den;result=struct('status','PASS','algorithmVersion','Stage55-B-dual-branch-visible-metric-v1','channel','AWGN','mode','controlled-time','snrDb',-21,'eligibleFrames',eligible,'methodNames',{c.methodNames},'rawErrors',errors,'denominators',den,'metrics',metrics,'conditionsFrozen',true);folder=fullfile(root,'results','b_exploratory','dual_branch_v1');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,'mechanism_pass.mat'),'result','-v7.3');write(fullfile(folder,'mechanism_pass.json'),jsonencode(result,'PrettyPrint',true));
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
